<?php require '../config/auth.php';wajib_role('guru');require '../config/database.php';$uid=(int)$_SESSION['user'];$g=$conn->query("SELECT id FROM guru WHERE user_id=$uid")->fetch_assoc();$gid=(int)($g['id']??0);$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$act=$_POST['action']??'';try{if($act==='save'){$id=(int)($_POST['id']??0);$sid=(int)$_POST['siswa_id'];$mid=(int)$_POST['mengajar_id'];$kkm=(float)$_POST['kkm'];$np=(float)$_POST['nilai_pengetahuan'];$nk=(float)$_POST['nilai_keterampilan'];$ket=trim($_POST['keterangan']);if($id){$st=$conn->prepare('UPDATE nilai_siswa n JOIN mengajar m ON m.id=n.mengajar_id SET n.kkm=?,n.nilai_pengetahuan=?,n.nilai_keterampilan=?,n.keterangan=? WHERE n.id=? AND m.guru_id=?');$st->bind_param('dddsii',$kkm,$np,$nk,$ket,$id,$gid);}else{$st=$conn->prepare('INSERT INTO nilai_siswa(siswa_id,mengajar_id,kkm,nilai_pengetahuan,nilai_keterampilan,keterangan) SELECT ?,m.id,?,?,?,? FROM mengajar m WHERE m.id=? AND m.guru_id=?');$st->bind_param('idddsii',$sid,$kkm,$np,$nk,$ket,$mid,$gid);}if(!$st->execute())throw new Exception('Data nilai gagal disimpan. Periksa apakah nilai siswa sudah pernah dimasukkan.');$msg='Nilai berhasil disimpan.';}elseif($act==='delete'){$id=(int)$_POST['id'];$st=$conn->prepare('DELETE n FROM nilai_siswa n JOIN mengajar m ON m.id=n.mengajar_id WHERE n.id=? AND m.guru_id=?');$st->bind_param('ii',$id,$gid);$st->execute();$msg='Nilai dihapus.';}}catch(Throwable $e){$err=$e->getMessage();}}
$mid=(int)($_GET['mengajar']??0);$classPer=(int)($_GET['per']??10);if(!in_array($classPer,[10,15,20,25,50],true))$classPer=10;$classPage=max(1,(int)($_GET['page']??1));$classSearch=trim($_GET['cari']??'');$classLike='%'.$conn->real_escape_string($classSearch).'%';$classWhere="mg.guru_id=$gid AND (k.nama_kelas LIKE '$classLike' OR mp.nama_mapel LIKE '$classLike' OR mp.kode_mapel LIKE '$classLike')";$classTotal=(int)$conn->query("SELECT COUNT(*) n FROM mengajar mg JOIN kelas k ON k.id=mg.kelas_id JOIN mapel mp ON mp.id=mg.mapel_id WHERE $classWhere")->fetch_assoc()['n'];$classPages=max(1,(int)ceil($classTotal/$classPer));$classPage=min($classPage,$classPages);$classes=$conn->query("SELECT mg.id,k.nama_kelas,mp.nama_mapel,mp.kode_mapel,(SELECT COUNT(*) FROM siswa s WHERE s.kelas=k.nama_kelas) jumlah FROM mengajar mg JOIN kelas k ON k.id=mg.kelas_id JOIN mapel mp ON mp.id=mg.mapel_id WHERE $classWhere ORDER BY k.nama_kelas LIMIT $classPer OFFSET ".(($classPage-1)*$classPer));$edit=null;if(isset($_GET['edit'])){$eid=(int)$_GET['edit'];$edit=$conn->query("SELECT n.*,s.nama_lengkap,s.id siswa_id,n.mengajar_id FROM nilai_siswa n JOIN siswa s ON s.id=n.siswa_id JOIN mengajar m ON m.id=n.mengajar_id WHERE n.id=$eid AND m.guru_id=$gid")->fetch_assoc();}
$selected=$conn->query("SELECT mg.id,k.nama_kelas,mp.nama_mapel FROM mengajar mg JOIN kelas k ON k.id=mg.kelas_id JOIN mapel mp ON mp.id=mg.mapel_id WHERE mg.id=$mid AND mg.guru_id=$gid")->fetch_assoc();$rows=$mid?$conn->query("SELECT n.*,s.nama_lengkap FROM nilai_siswa n JOIN siswa s ON s.id=n.siswa_id WHERE n.mengajar_id=$mid ORDER BY s.nama_lengkap"):false;$students=$selected?$conn->query("SELECT id,nama_lengkap FROM siswa WHERE kelas='".$conn->real_escape_string($selected['nama_kelas'])."' ORDER BY nama_lengkap"):false;$per=(int)($_GET['per']??10);if(!in_array($per,[10,15,20,25,50],true))$per=10;$page=max(1,(int)($_GET['page']??1));$search=trim($_GET['cari']??'');$list=[];if($mid&&$rows){while($x=$rows->fetch_assoc())if($search===''||stripos($x['nama_lengkap'],$search)!==false)$list[]=$x;}$total=$mid?count($list):0;$pages=max(1,(int)ceil($total/$per));$page=min($page,$pages);$list=array_slice($list,($page-1)*$per,$per);function gp($n){$q=$_GET;$q['page']=$n;return '?'.http_build_query($q);}?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nilai Siswa - SIPN</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="main"><header class="topbar"><div><p class="eyebrow">PANEL GURU</p><h1>Nilai Siswa</h1></div><div class="user-pill">Guru · <?=nama_user()?></div></header><nav class="role-nav"><details class="role-menu"><summary><span>☰</span> Menu</summary><div class="role-menu-links"><form method="get" class="role-menu-search"><input name="cari" placeholder="Cari menu / data..."></form><div class="role-login-as">Login sebagai: <b>Guru</b></div><a href="index.php">Home</a><a class="active" href="nilai.php">Nilai Siswa</a><a href="../profile.php">Profile</a><a href="../profile.php">Pengaturan</a><a href="../logout.php">Logout</a></div></details></nav><?php if($msg):?><div class="success"><?=h($msg)?></div><?php endif;?><?php if($err):?><div class="alert"><?=h($err)?></div><?php endif;?>
<?php if(!$mid):?><section class="panel"><h2>Daftar kelas dan mata pelajaran yang diajar</h2><form method="get" class="toolbar"><select name="per"><option value="10" <?=$classPer===10?'selected':''?>>10</option><option value="15" <?=$classPer===15?'selected':''?>>15</option><option value="20" <?=$classPer===20?'selected':''?>>20</option><option value="25" <?=$classPer===25?'selected':''?>>25</option><option value="50" <?=$classPer===50?'selected':''?>>50</option></select><input name="cari" value="<?=h($classSearch)?>" placeholder="Cari kelas atau mata pelajaran..."><button class="btn primary">Cari</button></form><div class="table-wrap"><table><tr><th>No</th><th>Kelas</th><th>Mata pelajaran</th><th>Jumlah siswa</th><th>Aksi</th></tr><?php $i=($classPage-1)*$classPer+1;while($c=$classes->fetch_assoc()):?><tr><td><?=$i++?></td><td><?=h($c['nama_kelas'])?></td><td><?=h($c['nama_mapel'])?></td><td><?=$c['jumlah']?></td><td><a class="edit-link" href="?mengajar=<?=$c['id']?>">Melihat</a></td></tr><?php endwhile;?><?php if($classTotal===0):?><tr><td colspan="5">Belum ada kelas atau mata pelajaran yang ditugaskan.</td></tr><?php endif;?></table></div><div class="pagination"><span>Menampilkan halaman <?=$classPage?> dari <?=$classPages?> · <?=$classTotal?> data</span><div><?php for($i=1;$i<=$classPages;$i++):if($i===1||$i===$classPages||abs($i-$classPage)<=1):?><a class="<?=$i===$classPage?'current':''?>" href="?<?=http_build_query(['per'=>$classPer,'cari'=>$classSearch,'page'=>$i])?>"><?=$i?></a><?php elseif(abs($i-$classPage)===2):?><a href="?<?=http_build_query(['per'=>$classPer,'cari'=>$classSearch,'page'=>$i])?>">…</a><?php endif;endfor;?></div></div></section><?php else:?><section class="panel"><h2>Nilai siswa · <?=h($selected['nama_kelas']??'')?> · <?=h($selected['nama_mapel']??'')?></h2><?php if($edit):?><form class="data-form" method="post"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$edit['id']?>"><input type="hidden" name="siswa_id" value="<?=$edit['siswa_id']?>"><input type="hidden" name="mengajar_id" value="<?=$edit['mengajar_id']?>"><h3>Edit Nilai Siswa</h3><label>Nama siswa</label><input value="<?=h($edit['nama_lengkap'])?>" disabled><label>KKM</label><input type="number" step="0.01" name="kkm" value="<?=$edit['kkm']?>"><label>Nilai pengetahuan</label><input type="number" step="0.01" name="nilai_pengetahuan" value="<?=$edit['nilai_pengetahuan']?>"><label>Nilai keterampilan</label><input type="number" step="0.01" name="nilai_keterampilan" value="<?=$edit['nilai_keterampilan']?>"><label>Keterangan</label><select name="keterangan"><option>Baik</option><option>Sangat Baik</option><option>Perlu Bimbingan</option></select><button class="btn primary">Simpan</button></form><?php else:?><form method="get" class="toolbar"><input type="hidden" name="mengajar" value="<?=$mid?>"><select name="per"><option>10</option><option>15</option><option>20</option><option>25</option><option>50</option></select><input name="cari" placeholder="Cari nama siswa" value="<?=h($search)?>"><button class="btn primary">Cari</button></form><div class="table-wrap"><table><tr><th>No</th><th>Nama siswa</th><th>KKM</th><th>Pengetahuan</th><th>Keterampilan</th><th>Nilai akhir</th><th>Keterangan</th><th>Aksi</th></tr><?php $i=($page-1)*$per+1;foreach($list as $r):$avg=($r['nilai_pengetahuan']+$r['nilai_keterampilan'])/2;?><tr><td><?=$i++?></td><td><?=h($r['nama_lengkap'])?></td><td><?=$r['kkm']?></td><td><?=$r['nilai_pengetahuan']?></td><td><?=$r['nilai_keterampilan']?></td><td><?=number_format($avg,2)?></td><td><?=h($r['keterangan'])?></td><td><a class="edit-link" href="?mengajar=<?=$mid?>&edit=<?=$r['id']?>">Edit</a><form method="post" style="display:inline" onsubmit="return confirm('Hapus nilai?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="danger-link">Hapus</button></form></td></tr><?php endforeach;?></table></div><h3>Tambah Nilai Siswa</h3><form method="post" class="data-form"><input type="hidden" name="action" value="save"><input type="hidden" name="mengajar_id" value="<?=$mid?>"><label>Nama siswa</label><select name="siswa_id" required><?php if($students)while($s=$students->fetch_assoc()):?><option value="<?=$s['id']?>"><?=h($s['nama_lengkap'])?></option><?php endwhile;?></select><label>KKM</label><input type="number" step="0.01" name="kkm" value="75"><label>Nilai pengetahuan</label><input type="number" step="0.01" name="nilai_pengetahuan" required><label>Nilai keterampilan</label><input type="number" step="0.01" name="nilai_keterampilan" required><label>Keterangan</label><select name="keterangan"><option>Baik</option><option>Sangat Baik</option><option>Perlu Bimbingan</option></select><button class="btn primary">Tambah Nilai</button></form><div class="pagination"><span>Menampilkan halaman <?=$page?> dari <?=$pages?></span><div><?php for($i=1;$i<=$pages;$i++):?><a class="<?=$i===$page?'current':''?>" href="<?=gp($i)?>"><?=$i?></a><?php endfor;?></div></div><?php endif;?></section><?php endif;?></main></body></html>